-- Mide el count de /api/search para varias palabras (3 corridas cada una; mirar la 3ª, con la cache caliente).
-- Correr contra azul_massive_load. Ver docker exec ... -f en el mensaje del hilo.
\timing on

\echo === catering
SELECT 'catering' AS palabra, count(*) AS total FROM "Providers" p WHERE p."Status" = 'Published' AND (f_matches(p."DisplayName", lower('%catering%')) OR f_matches(p."Description", lower('%catering%')) OR EXISTS (SELECT 1 FROM "ProviderOfferings" p0 JOIN "Offerings" o ON p0."OfferingId" = o."Id" WHERE p."Id" = p0."ProviderId" AND f_matches(o."Name", lower('%catering%'))));
SELECT 'catering' AS palabra, count(*) AS total FROM "Providers" p WHERE p."Status" = 'Published' AND (f_matches(p."DisplayName", lower('%catering%')) OR f_matches(p."Description", lower('%catering%')) OR EXISTS (SELECT 1 FROM "ProviderOfferings" p0 JOIN "Offerings" o ON p0."OfferingId" = o."Id" WHERE p."Id" = p0."ProviderId" AND f_matches(o."Name", lower('%catering%'))));
SELECT 'catering' AS palabra, count(*) AS total FROM "Providers" p WHERE p."Status" = 'Published' AND (f_matches(p."DisplayName", lower('%catering%')) OR f_matches(p."Description", lower('%catering%')) OR EXISTS (SELECT 1 FROM "ProviderOfferings" p0 JOIN "Offerings" o ON p0."OfferingId" = o."Id" WHERE p."Id" = p0."ProviderId" AND f_matches(o."Name", lower('%catering%'))));

